//! Compare observable orchestration with fixtures generated by the TypeScript executor.
mod support;
use fujo::Cli;
use fujo::CliError;
use fujo::Command;
use fujo::RunOptions;
use fujo::flag;
use fujo::json;
use fujo::output::ActivityEvent;
use fujo::prompt::Answer;
use fujo::prompt::Prompt;
use fujo::prompt::TestPrompter;
use std::sync::Arc;
use std::sync::Mutex;

#[test]
fn matches_typescript_lifecycle_contract() {
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/lifecycle.json")).unwrap();
    let parsing: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/reference.json")).unwrap();
    assert_eq!(reference["sourceCommit"], parsing["sourceCommit"]);
    for expected in reference["fixtures"].as_array().unwrap() {
        let name = expected["name"].as_str().unwrap();
        let trace = Arc::new(Mutex::new(Vec::<String>::new()));
        let mut options = RunOptions::default();
        let command = if name.starts_with("prompt-skip-") {
            let input = flag::string("name").prompt(Prompt::input("Name?"));
            options.resolve.prompter = Some(Arc::new(TestPrompter::new([Answer::Skip])));
            if name.ends_with("required") {
                let input = input.required();
                Command::new("demo").inputs(input).action(|ctx, value, ()| {
                    ctx.out.log(value);
                    Ok(())
                })
            } else {
                Command::new("demo")
                    .inputs(input.default("fallback".into()))
                    .action(|ctx, value, ()| {
                        ctx.out.log(value);
                        Ok(())
                    })
            }
        } else {
            let scenario = name.to_owned();
            let events = trace.clone();
            let command = Command::new("demo").middleware_async(async move |ctx, next| {
                events.lock().unwrap().push("outer:before".into());
                let mut result = next.run(ctx).await;
                if result.is_err() {
                    events.lock().unwrap().push("caught".into());
                    if scenario == "transform-error" {
                        result = Err(CliError::new("WRAPPED", "wrapped").exit_code(2));
                    }
                }
                events.lock().unwrap().push("outer:after".into());
                result
            });
            let scenario = name.to_owned();
            let events = trace.clone();
            let command = command.middleware_async(async move |ctx, next| {
                events.lock().unwrap().push("inner:before".into());
                let result = if scenario == "short-circuit" {
                    Ok(())
                } else {
                    next.run(ctx).await
                };
                events.lock().unwrap().push("inner:after".into());
                result
            });
            let scenario = name.to_owned();
            let events = trace.clone();
            let command = command.derive_async(async move |_| {
                events.lock().unwrap().push("derive".into());
                support::yield_once().await;
                if scenario == "derive-failure" {
                    return Err(CliError::new("DENIED", "denied").exit_code(2));
                }
                Ok(7_u16)
            });
            let scenario = name.to_owned();
            let events = trace.clone();
            options.output.json = name == "json";
            command.action_async(async move |ctx| {
                events.lock().unwrap().push("action".into());
                support::yield_once().await;
                let _spinner = (scenario == "activity-failure").then(|| ctx.out.spinner("work"));
                if ["action-failure", "transform-error", "activity-failure"]
                    .contains(&scenario.as_str())
                {
                    return Err(CliError::new("FAILED", "failed").exit_code(2));
                }
                if scenario == "activities" {
                    ctx.out.spinner("work").succeed("ready");
                    let mut progress = ctx.out.progress("items", 2);
                    progress.update(1);
                    progress.done("done");
                }
                if scenario == "exit-code" {
                    ctx.out.set_exit_code(3);
                }
                if scenario == "json" {
                    ctx.out.json(&json!({"value":ctx.state::<u16>()?}))?;
                } else {
                    ctx.out.log(ctx.state::<u16>()?);
                }
                Ok(())
            })
        };
        let result = support::run(
            Cli::new("demo")
                .default(command)
                .execute_async(Vec::<String>::new(), options),
        );
        let actual = json!({
            "name": name, "trace": *trace.lock().unwrap(), "exitCode": result.exit_code,
            "code": result.error.map(|e| e.code), "stdout": result.stdout,
            "starts": result.activities.iter().filter(|e| matches!(e, ActivityEvent::Start{..})).count(),
            "finishes": result.activities.iter().filter(|e| matches!(e, ActivityEvent::Finish{..})).count(),
        });
        let mut expected = expected.clone();
        if name == "activity-failure" {
            // TS capture does not record framework cleanup. Rust's handle Drop
            // explicitly records a failed completion; preserve that guarantee.
            assert_eq!(expected["finishes"], 0);
            expected["finishes"] = json!(1);
        }
        assert_eq!(actual, expected, "lifecycle case {name}");
    }
}
